typedef int int32;
typedef float rational_t;
typedef float time_value_t;

class entity_track_node
{
  int32 id;
  int32 owner;
  char pad[16];
  entity_track_node* m_child;
  entity_track_node* m_sibling;
  void* m_prs_track;
  void* m_signal_track;
  int32 more_pad[4];

public:
  entity_track_node();
  ~entity_track_node();
};

enum { MAX_ROOT_NODES = 4 };

class entity_track_tree
{
  char file_header[4];
  unsigned int version;
  int32 num_root_nodes;
  rational_t floor_offset;
  time_value_t duration;
  int32 total_nodes;
  int32 pad[2];
  entity_track_node root_nodes[MAX_ROOT_NODES];

public:
  entity_track_node* insert_root();
};

entity_track_node* entity_track_tree::insert_root()
{
  // shift roots
  num_root_nodes++;
  int i;
  for( i=num_root_nodes-1; i>0; i-- )
    root_nodes[i] = root_nodes[i-1];
  root_nodes[0] = entity_track_node();
  return root_nodes;
}
